import { ListenBrainzClient } from "listenbrainz-api";

const lb = new ListenBrainzClient({
  userAgent: "MyApp/1.0 (https://example.com)",
  token: process.env.LISTENBRAINZ_TOKEN,
});

const response = await lb.getListens("username", { count: 10 });
console.log(response.payload.listens);

const result = await lb.request<{ payload: { count: number } }>({
  method: "GET",
  path: `/1/user/${encodeURIComponent("username")}/listen-count`,
  query: { range: "all_time", extra_info: 1 },
});

const response = await lb.getListens("alice", {
  count: 20,
  maxTs: Math.floor(Date.now() / 1000),
  musicBrainzMetadata: true,
});

for (const listen of response.payload.listens) {
  console.log(listen.track_metadata.artist_name, listen.track_metadata.track_name);
}

const now = await lb.getPlayingNow("alice");
const current = now.payload.listens[0];
if (current) {
  console.log(current.track_metadata.track_name);
}

const response = await lb.getArtistStats("alice", {
  range: "all_time", count: 10, offset: 0,
});
const top = response.payload.artists;
const distinctArtists = await lb.getArtistCount("alice");

import { createListen } from "listenbrainz-api";

await lb.submitListen(token, createListen({
  artistName: "Daft Punk",
  trackName: "One More Time",
  listenedAt: Math.floor(Date.now() / 1000),
}));

import { createNowPlaying } from "listenbrainz-api";

await lb.submitNowPlaying(token, createNowPlaying({
  artistName: "Daft Punk",
  trackName: "One More Time",
  durationMs: 320_000,
}));

const match = await lb.lookupTrackMetadata({
  artistName: "Radiohead",
  recordingName: "Paranoid Android",
});
if (match.recording_mbid) {
  const detail = await lb.getRecordingMetadata(match.recording_mbid);
  console.log(detail.title);
}

import { MusicBrainzClient } from "listenbrainz-api";

const mb = new MusicBrainzClient({
  userAgent: "MyApp/1.0 (https://example.com)",
});
const matches = await mb.searchRecording("Paranoid Android", 5);
const detail = matches[0]
  ? await mb.lookupRecording(matches[0].id)
  : undefined;

